function exportBlockHTML(premium){const unlocked=customerUnlocked();if(premium&&!unlocked)return `<div class="formsec"><h3>Premium selected</h3><p class="muted">Export/print is locked. Send order on WhatsApp with full CV data. Already paid? Click Order and enter your access code.</p><button class="btn pink" onclick="openOrder()">Order / Payment Options</button></div>`;if(premium&&unlocked)return `<div class="formsec"><h3>Premium unlocked</h3><p class="muted">Your access code was accepted. You can print/save PDF or download Word.</p><div class="actions"><button class="btn green" onclick="exportPDF()">Print / Save PDF</button><button class="btn dark" onclick="exportWord()" id="wordBtn">Download Word</button></div></div>`;return `<div class="formsec"><h3>Free export</h3><p class="muted">Free template selected. You can print/save PDF or download Word.</p><div class="actions"><button class="btn green" onclick="exportPDF()">Print / Save PDF</button><button class="btn dark" onclick="exportWord()" id="wordBtn">Download Word</button><button class="btn pink" onclick="openOrder()">Order Expert CV</button></div></div>`}
function stepHTML(){const f=state.form,premium=isPremium();if(state.step===1)return `<div class="guided"><b>Start here</b><p class="muted small">New user? Press demo first. You can change template again at the final step without losing data.</p></div><div class="formsec"><h3>Quick start</h3><div class="actions"><button class="btn dark" onclick="fillDemo()">Fill Full Demo CV</button><button class="btn light" onclick="clearAll()">Clear All Data</button><button class="btn" onclick="setStep(2)">Start From Scratch</button></div></div><div class="formsec"><h3>Choose Template</h3><div class="layout-list">${templates.map(t=>`<button class="layout-btn ${state.template===t.id?'active':''}" onclick="setTemplate('${t.id}')"><b>${t.name}</b><br><span>${t.premium?'Premium':'Free'} · ${t.cat}</span></button>`).join('')}</div></div><div class="formsec"><h3>Import old resume text</h3><textarea placeholder="Paste old resume text here" oninput="setField('form.pasteResume',this.value)">${esc(f.pasteResume)}</textarea><button class="btn light" onclick="importResume()">Import Basic Details</button></div><div class="actions"><button class="btn" onclick="setStep(2)">Next: Personal Details</button></div>`;if(state.step===2)return `<div class="formsec"><h3>Personal Details</h3><div class="row"><div><label>Name</label><input value="${esc(f.name)}" oninput="setField('form.name',this.value)"></div><div><label>Job Title</label><input value="${esc(f.job)}" oninput="setField('form.job',this.value)"></div></div><div class="row"><div><label>Phone</label><input value="${esc(f.phone)}" oninput="setField('form.phone',this.value)"></div><div><label>Email</label><input value="${esc(f.email)}" oninput="setField('form.email',this.value)"></div></div><label>Address</label><input value="${esc(f.address)}" oninput="setField('form.address',this.value)"><label>Summary</label><textarea id="summaryField" oninput="setField('form.summary',this.value)">${esc(f.summary)}</textarea><button class="btn orange" onclick="aiSummary()">Suggest Ready-Made Summary</button></div><div class="formsec"><h3>Profile Photo</h3><div class="row"><div><label>Upload Photo</label><input type="file" accept="image/*" onchange="handlePhoto(this)"></div><div><label>Photo Position</label><select onchange="setField('photoPlacement',this.value)"><option value="auto" ${state.photoPlacement==='auto'?'selected':''}>Auto by template</option><option value="none" ${state.photoPlacement==='none'?'selected':''}>No photo</option><option value="top" ${state.photoPlacement==='top'?'selected':''}>Top/Header</option><option value="side" ${state.photoPlacement==='side'?'selected':''}>Sidebar/Side</option><option value="right" ${state.photoPlacement==='right'?'selected':''}>Right side</option></select></div></div><div class="photo-tools"><div><label>Zoom</label><input type="range" min="1" max="1.9" step=".05" value="${state.photoFit.zoom}" oninput="setPhotoFit('zoom',this.value)"></div><div><label>Move Left/Right</label><input type="range" min="0" max="100" value="${state.photoFit.x}" oninput="setPhotoFit('x',this.value)"></div><div><label>Move Up/Down</label><input type="range" min="0" max="100" value="${state.photoFit.y}" oninput="setPhotoFit('y',this.value)"></div></div>${photoFrameHTML()}</div><div class="actions"><button class="btn light" onclick="setStep(1)">Back</button><button class="btn" onclick="setStep(3)">Next: Sections</button></div>`;if(state.step===3)return `<div class="formsec"><h3>Experience</h3><label>Experience 1</label><input placeholder="Job title" value="${esc(f.exp1t)}" oninput="setField('form.exp1t',this.value)"><input placeholder="Company" value="${esc(f.exp1c)}" oninput="setField('form.exp1c',this.value)"><textarea placeholder="Description" oninput="setField('form.exp1d',this.value)">${esc(f.exp1d)}</textarea><label>Experience 2</label><input placeholder="Job title" value="${esc(f.exp2t)}" oninput="setField('form.exp2t',this.value)"><input placeholder="Company" value="${esc(f.exp2c)}" oninput="setField('form.exp2c',this.value)"><textarea placeholder="Description" oninput="setField('form.exp2d',this.value)">${esc(f.exp2d)}</textarea></div><div class="formsec"><h3>Education</h3><input placeholder="Degree / Certificate" value="${esc(f.edu1t)}" oninput="setField('form.edu1t',this.value)"><input placeholder="Institute" value="${esc(f.edu1c)}" oninput="setField('form.edu1c',this.value)"><textarea placeholder="Details" oninput="setField('form.edu1d',this.value)">${esc(f.edu1d)}</textarea><input placeholder="Second Degree / Certificate" value="${esc(f.edu2t)}" oninput="setField('form.edu2t',this.value)"><input placeholder="Institute" value="${esc(f.edu2c)}" oninput="setField('form.edu2c',this.value)"><textarea placeholder="Details" oninput="setField('form.edu2d',this.value)">${esc(f.edu2d)}</textarea></div><div class="formsec"><h3>Skills</h3><label><input type="checkbox" ${state.skillBars?'checked':''} onchange="state.skillBars=this.checked;saveAuto();refreshPreview()"> Show skill bars</label>${skillRows()}<button class="btn light" onclick="addSkill()">Add Skill</button><label>Soft Skills</label><textarea oninput="setField('form.soft',this.value)">${esc(f.soft)}</textarea><label>Languages</label><textarea oninput="setField('form.lang',this.value)">${esc(f.lang)}</textarea></div><div class="formsec"><h3>Extra Sections</h3><label>Projects</label><textarea oninput="setField('form.projects',this.value)">${esc(f.projects)}</textarea><label>Certifications</label><textarea oninput="setField('form.certs',this.value)">${esc(f.certs)}</textarea><label>References</label><textarea oninput="setField('form.refs',this.value)">${esc(f.refs)}</textarea><div class="row"><div><label>Custom Title</label><input value="${esc(f.customTitle)}" oninput="setField('form.customTitle',this.value)"></div><div><label>Custom Text</label><input value="${esc(f.customBody)}" oninput="setField('form.customBody',this.value)"></div></div></div><div class="formsec"><h3>Show / Hide Sections</h3><div class="switchgrid">${Object.entries({summary:'Summary',experience:'Experience',education:'Education',tech:'Technical Skills',soft:'Soft Skills',lang:'Languages',projects:'Projects',certs:'Certifications',refs:'References',custom:'Custom'}).map(([k,v])=>`<label class="switchline"><input type="checkbox" ${state.show[k]?'checked':''} onchange="state.show['${k}']=this.checked;saveAuto();refreshPreview()"> ${v}</label>`).join('')}</div></div><div class="actions"><button class="btn light" onclick="setStep(2)">Back</button><button class="btn" onclick="setStep(4)">Next: Design & Export</button></div>`;return `<div class="formsec"><h3>Change Template Anytime</h3><p class="muted small">Data safe rahega. Yahan se final template select kar sakte hain.</p><div class="layout-list">${templates.map(t=>`<button class="layout-btn ${state.template===t.id?'active':''}" onclick="setTemplate('${t.id}')"><b>${t.name}</b><br><span>${t.premium?'Premium':'Free'} · ${t.cat}</span></button>`).join('')}</div></div><div class="formsec"><h3>Custom Theme <span class="tag premium">Premium</span></h3><div class="actions"><button class="btn light" onclick="applyThemePreset('blue')">Blue Pro</button><button class="btn light" onclick="applyThemePreset('green')">Emerald</button><button class="btn light" onclick="applyThemePreset('gold')">Executive Gold</button><button class="btn light" onclick="applyThemePreset('peach')">Soft Peach</button><button class="btn light" onclick="applyThemePreset('minimal')">Minimal</button></div>${(customerUnlocked()||ownerMode)?`<details><summary class="btn light" style="margin-top:10px">Advanced Customization</summary><div class="row3"><div><label>Main Color</label><input type="color" value="${state.theme.main}" onchange="state.customTheme=true;setField('theme.main',this.value)"></div><div><label>Accent Color</label><input type="color" value="${state.theme.accent}" onchange="state.customTheme=true;setField('theme.accent',this.value)"></div><div><label>CV Background</label><input type="color" value="${state.theme.bg}" onchange="state.customTheme=true;setField('theme.bg',this.value)"></div><div><label>Text Color</label><input type="color" value="${state.theme.text}" onchange="state.customTheme=true;setField('theme.text',this.value)"></div><div><label>Heading Color</label><input type="color" value="${state.theme.heading}" onchange="state.customTheme=true;setField('theme.heading',this.value)"></div><div><label>Section Style</label><select onchange="state.customTheme=true;setField('theme.section',this.value)"><option value="soft" ${state.theme.section==='soft'?'selected':''}>Soft Cards</option><option value="clean" ${state.theme.section==='clean'?'selected':''}>Clean Lines</option><option value="sharp" ${state.theme.section==='sharp'?'selected':''}>Sharp Executive</option></select></div><div><label>Spacing</label><select onchange="state.customTheme=true;setField('theme.spacing',this.value)"><option value="compact" ${state.theme.spacing==='compact'?'selected':''}>Compact</option><option value="normal" ${state.theme.spacing==='normal'?'selected':''}>Normal</option><option value="airy" ${state.theme.spacing==='airy'?'selected':''}>Airy</option></select></div><div><label>Corners</label><select onchange="state.customTheme=true;setField('theme.corner',this.value)"><option value="rounded" ${state.theme.corner==='rounded'?'selected':''}>Rounded</option><option value="sharp" ${state.theme.corner==='sharp'?'selected':''}>Sharp</option></select></div></div></details>`:'<p class="muted small">🔒 Advanced Customization (colors, spacing, corners) unlocks after you order and enter your access code.</p>'}</div>${exportBlockHTML(premium)}<div class="formsec"><h3>Save Work</h3><button class="btn light" onclick="saveDraft()">Save Draft</button><button class="btn light" onclick="loadDraft()">Load Draft</button><button class="btn danger" onclick="clearAll()">Clear All Data</button></div><div class="formsec owner-tools"><h3>Owner Order Tools</h3><textarea placeholder="Paste structured WhatsApp order" oninput="setField('form.pasteOrder',this.value)">${esc(f.pasteOrder)}</textarea><button class="btn orange" onclick="importStructured()">Import Order Text</button><button class="btn light" onclick="downloadOrderFile()">Download Current Order File</button><label>Import order file</label><input type="file" accept="application/json" onchange="importOrderFile(this)"><textarea readonly>${esc(orderText())}</textarea></div><div class="actions"><button class="btn light" onclick="setStep(3)">Back</button></div>`}
function builderHTML(){document.body.classList.toggle('owner',ownerMode);return `<nav class="nav"><div class="brand">CV Studio <span>Pro</span></div><div class="links"><a href="index.html">Home</a><a href="templates.html">Templates</a><a href="pricing.html">Pricing</a><a href="contact.html">Contact</a></div></nav><div class="paywall" id="paywall"><div class="paybox"><h2>Premium export locked</h2><p class="muted">This template or custom theme is premium. Send your order on WhatsApp. Your full CV data will be included automatically.</p><div class="status">Status: Received → In Progress → Delivered</div><div class="actions"><button class="btn pink" id="sendOrderBtn" onclick="whatsappOrder()">Send Order on WhatsApp</button><button class="btn light" onclick="closeOrder()">Close</button></div><div class="unlockbox"><label>Already paid? Enter your access code</label><input id="unlockInput" placeholder="Enter access code"><button class="btn dark" onclick="tryUnlockAccess()">Unlock My CV</button><p class="muted small" id="unlockMsg"></p></div></div></div><div class="builder"><div class="formpanel"><div class="steps">${[1,2,3,4].map(n=>`<button class="step ${state.step===n?'active':''}" onclick="setStep(${n})">${['Start','Details','Sections','Design & Export'][n-1]}</button>`).join('')}</div>${stepHTML()}</div><div class="previewpanel"><div class="preview-toolbar"><b>Live CV Preview</b><p class="muted small">CV full view. If data is long, next page appears below.</p><button class="btn light small" onclick="document.getElementById('cvPreview')?.scrollTo({top:0,behavior:'smooth'})">Top of CV</button></div><div id="cvPreview">${renderCV()}</div></div></div>`}
function mini(t){const c=t.accent;const sq=['t1','t2','t4','t6','t9','t10','t11','t15','t19'].includes(t.id)?' sq':'';let body='';const lines='<div class="mini-line"></div><div class="mini-line" style="width:88%"></div><div class="mini-line" style="width:65%"></div><div class="mini-sec"><div class="mini-line" style="width:40%"></div><div class="mini-line"></div><div class="mini-line" style="width:82%"></div><div class="mini-line" style="width:60%"></div></div><div class="mini-sec"><div class="mini-line" style="width:35%"></div><div class="mini-line" style="width:75%"></div></div><div class="mini-sec"><div class="mini-line" style="width:45%"></div><div class="mini-line" style="width:55%"></div></div>';if(['t1','t9','t11'].includes(t.id))body=`<div class="mini-side" style="background:${t.id==='t11'?'#581c87':t.id==='t9'?'#0f766e':'#111827'}"><div class="mini-photo${sq}"></div><div class="mini-line light"></div><div class="mini-line light"></div></div><div class="mini-main">${lines}</div>`;else if(['t2','t10','t15'].includes(t.id))body=`<div class="mini-banner" style="background:${t.id==='t10'?'#334155':t.id==='t15'?'#7c3aed':'#16a34a'}"><div class="mini-photo${sq}"></div><div><div class="mini-line light" style="width:90px"></div><div class="mini-line light" style="width:60px"></div></div></div><div class="mini-grid">${lines}${lines}</div>`;else if(t.id==='t6')body=`<div class="mini-exec-head"><div><div class="mini-line light" style="width:90px"></div><div class="mini-line light" style="width:55px"></div></div><div class="mini-photo${sq}"></div></div><div class="mini-grid"><div class="mini-sec" style="background:#fef3c7"></div>${lines}</div>`;else if(t.id==='t16')body=`<div class="mini-cv mini-diagonal"><div style="position:relative;padding:18px 12px 0 80px"><div class="mini-photo${sq}"></div><div class="mini-line dark"></div></div><div class="mini-grid">${lines}${lines}</div></div>`;else if(t.id==='t17')body=`<div style="height:95px;background:radial-gradient(circle at 50% -10%,#0ea5e9 0 55%,#fff 56%);padding:16px;text-align:center"><div class="mini-photo${sq}" style="margin:auto"></div></div><div class="mini-grid">${lines}${lines}</div>`;else if(t.id==='t18')body=`<div style="height:85px;background:linear-gradient(135deg,#111827 0 58%,#facc15 58%);padding:16px;color:white"><div class="mini-photo${sq}"></div></div><div class="mini-grid">${lines}${lines}</div>`;else body=`<div style="padding:14px;border-top:7px solid ${c}"><div class="mini-photo${sq}"></div>${lines}</div>`;return `<div class="template-thumb"><div class="mini-cv">${body}</div></div>`}
function templateCard(t){return `<div class="template-card ${t.premium?'premium-card':''} ${t.id==='t6'?'featured-template':''}">${mini(t)}<h3>${t.name}</h3><div><span class="tag ${t.premium?'premium':'free'}">${t.premium?'Premium':'Free'}</span><span class="tag">${t.cat}</span></div><p class="muted small">Full CV preview with different structure, not only colors.</p><div class="actions"><a class="btn light" href="builder.html?template=${t.id}">Use Template</a><a class="btn dark" href="builder.html?fresh=1">Start Fresh</a></div></div>`}
function renderHomeTemplates(){const el=document.getElementById('homeTemplates');const featuredIds=['t1','t2','t19','t20','t16','t9'];const picked=featuredIds.map(id=>templates.find(t=>t.id===id)).filter(Boolean);if(el)el.innerHTML=picked.map(templateCard).join('')}
function renderTemplatePage(){let active='All';const tabs=document.getElementById('tabs'),grid=document.getElementById('templateGrid');function draw(){tabs.innerHTML=categories.map(c=>`<button class="tab ${active===c?'active':''}" onclick="window.__setCat('${c}')">${c}</button>`).join('');grid.innerHTML=templates.filter(t=>active==='All'||(active==='Free'&&!t.premium)||(active==='Premium'&&t.premium)||t.cat===active).map(templateCard).join('')}window.__setCat=c=>{active=c;draw()};draw()}
function initBuilder(){loadAuto();const q=new URLSearchParams(location.search);if(q.get('template'))state.template=q.get('template');if(q.get('fresh')==='1'){clearAll();return}fullRender()}
